export default pattern<
  IframeHighlightsExchangeInput,
  IframeHighlightsExchangeOutput
>(({
  input,
  state,
}) => {
  const output = new Writable<IframeOutputData>(DEFAULT_OUTPUT);
  const context = IframeContext({
    input,
    state,
    output,
  });

  return {
    [NAME]: "Iframe · Highlights exchange",
    [UI]: (
      <div style={{ width: "100%", height: "760px" }}>
        <cf-iframe
          src={GUEST_HTML}
          $context={context}
          resourceKinds={{
            input: "readonly",
          } as const}
        />
      </div>
    ),
    state,
    output,
  };
});
